editor.addEventListener('pointerdown',e=>{const last=editor.lastElementChild;paperClick=e.target===editor&&(!last||e.clientY>last.getBoundingClientRect().bottom)});
converter.addRule('intentionalBlank',{filter:n=>n.tagName==='P'&&!n.textContent.trim()&&!n.querySelector('img')&&(!n.children.length||[...n.children].every(c=>c.tagName==='BR')),replacement:()=>'<p><br></p>\n\n'});
function currentPre(){const n=window.getSelection().anchorNode;const el=n?.nodeType===1?n:n?.parentElement;return el&&editor.contains(el)?el.closest('pre'):null}
function exitCode(){const pre=currentPre();if(!pre)return;let p=pre.nextElementSibling;if(!p||p.tagName!=='P'){p=blankParagraph();pre.after(p)}placeCaret(p);update()}
function insertMediaBlock(html,selector){restoreSelection();const sel=window.getSelection(),r=sel.getRangeAt(0);r.deleteContents();const template=document.createElement('template');template.innerHTML=html;const node=template.content.querySelector(selector);let anchor=r.startContainer.nodeType===1?r.startContainer:r.startContainer.parentElement;while(anchor.parentElement&&anchor.parentElement!==editor&&!['TD','TH'].includes(anchor.parentElement.tagName))anchor=anchor.parentElement;if(anchor!==editor&&editor.contains(anchor))anchor.after(template.content);else r.insertNode(template.content);if(node){if(selector==='pre')placeCaret(node.querySelector('code')||node,true);else{const block=node.parentElement?.tagName==='P'?node.parentElement:node;let p=block.nextElementSibling;if(!p||p.tagName!=='P'){p=blankParagraph();block.after(p)}placeCaret(p)}}rememberSelection();update();return node}
$('codeblock').onmousedown=e=>e.preventDefault();$('codeblock').onclick=()=>{rememberSelection();const dialog=document.createElement('dialog');dialog.className='draft-dialog code-dialog';dialog.innerHTML='<form method="dialog"><h3>插入代码块</h3><label>语言<select aria-label="代码语言"><option value="">纯文本</option><option value="python">Python</option><option value="javascript">JavaScript</option><option value="html">HTML</option><option value="css">CSS</option><option value="json">JSON</option><option value="bash">Shell</option><option value="cpp">C++</option></select></label><textarea aria-label="代码内容" placeholder="粘贴或输入代码" spellcheck="false"></textarea><p class="table-help">代码中按 Enter 换行，Tab 缩进；Ctrl / ⌘ + Enter 或 Esc 回到正文。</p><div><button value="cancel">取消</button><button value="ok" class="primary">插入代码</button></div></form>';document.body.append(dialog);dialog.onclose=()=>{if(dialog.returnValue==='ok'){const pre=document.createElement('pre'),code=document.createElement('code');const language=dialog.querySelector('select').value;if(language)code.className='language-'+language;code.textContent=dialog.querySelector('textarea').value||'\n';pre.append(code);insertMediaBlock(pre.outerHTML,'pre')}dialog.remove()};dialog.showModal()};
$('photo').onmousedown=e=>e.preventDefault();$('photo').onclick=()=>{rememberSelection();$('photo-file').click()};
$('photo-file').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;const docId=active,savedRange=selection?.cloneRange();const button=$('photo');button.disabled=true;try{if(f.size>20*1024*1024)throw Error('请使用小于 20 MB 的图片');const url=URL.createObjectURL(f),img=new Image();try{img.src=url;await img.decode();const ratio=Math.min(1,1400/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*ratio));canvas.height=Math.max(1,Math.round(img.naturalHeight*ratio));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);const data=canvas.toDataURL('image/jpeg',.82);if(active!==docId||mode!=='visual')throw Error('文档已切换，请在目标文档中重新插入照片');selection=savedRange;const photo=document.createElement('img');photo.src=data;photo.alt=f.name;const before=editor.innerHTML;insertMediaBlock('<p>'+photo.outerHTML+'</p>','img');if(!flushSave()){editor.innerHTML=before;selection=null;flushSave();throw Error('草稿空间不足，请导出备份或删除不需要的草稿后再试')}toast('照片已插入并保存在草稿中')}finally{URL.revokeObjectURL(url)}}catch(error){toast(error.message||'图片无法读取，请使用 JPG、PNG 或 WebP')}finally{button.disabled=mode==='source'}};

converter.addRule('codeFence',{filter:'pre',replacement:(content,node)=>{const clone=node.cloneNode(true);clone.querySelectorAll('br').forEach(br=>br.replaceWith('\n'));const code=clone.querySelector('code');const language=code?.className.match(/language-([a-z0-9+-]+)/i)?.[1]||'';const text=(code||clone).textContent;const runs=text.match(/`+/g)||[];const fence='`'.repeat(Math.max(3,...runs.map(x=>x.length+1)));return '\n\n'+fence+language+'\n'+text.replace(/\n$/,'')+'\n'+fence+'\n\n'}});

var selectedPhoto=null,draggedPhoto=null;
function hideImageTools(){if(typeof selectedPhoto!=='undefined'&&selectedPhoto)selectedPhoto.classList.remove('image-selected');selectedPhoto=null;const bar=$('image-tools');if(bar)bar.hidden=true}
function photoBlock(img){let p=img.parentElement;if(p.tagName==='P'&&p.textContent.trim()===''&&p.querySelectorAll('img').length===1)return p;const block=document.createElement('p');const anchor=img.closest('p,div,figure')||img;anchor.after(block);block.append(img);return block}
function selectPhoto(img){hideImageTools();selectedPhoto=img;img.classList.add('image-selected');img.draggable=true;const width=parseFloat(img.style.width);const percent=img.style.width.endsWith('%')?width:Math.min(100,Math.round(img.getBoundingClientRect().width/img.parentElement.getBoundingClientRect().width*100));$('image-size').value=percent||100;$('image-size-label').textContent=(percent||100)+'%';$('image-tools').hidden=false}
editor.addEventListener('click',e=>{if(e.target.tagName==='IMG'){e.preventDefault();selectPhoto(e.target)}else hideImageTools()});
$('image-size').oninput=e=>{if(!selectedPhoto||!editor.contains(selectedPhoto))return hideImageTools();selectedPhoto.style.width=e.target.value+'%';selectedPhoto.style.height='auto';selectedPhoto.removeAttribute('height');selectedPhoto.removeAttribute('width');$('image-size-label').textContent=e.target.value+'%';update()};
document.querySelectorAll('[data-image-align]').forEach(button=>{button.onmousedown=e=>e.preventDefault();button.onclick=()=>{if(!selectedPhoto)return;photoBlock(selectedPhoto);const side=button.dataset.imageAlign;selectedPhoto.style.display='block';selectedPhoto.style.marginLeft=side==='left'?'0':'auto';selectedPhoto.style.marginRight=side==='right'?'0':'auto';update()}});
function movePhoto(direction){if(!selectedPhoto||!editor.contains(selectedPhoto))return;const block=photoBlock(selectedPhoto);const adjacent=direction==='up'?block.previousElementSibling:block.nextElementSibling;if(!adjacent)return;if(direction==='up')adjacent.before(block);else adjacent.after(block);update();block.scrollIntoView({block:'nearest'})}
$('image-up').onclick=()=>movePhoto('up');$('image-down').onclick=()=>movePhoto('down');$('image-done').onclick=hideImageTools;
editor.addEventListener('pointerdown',e=>{if(e.target.tagName==='IMG')e.target.draggable=true});
editor.addEventListener('dragstart',e=>{if(e.target.tagName!=='IMG')return;draggedPhoto=e.target;e.dataTransfer.setData('application/x-zhuanyan-photo','move');e.dataTransfer.effectAllowed='move'});
editor.addEventListener('dragover',e=>{if(draggedPhoto&&editor.contains(draggedPhoto)){e.preventDefault();e.dataTransfer.dropEffect='move'}});
editor.addEventListener('drop',e=>{if(!draggedPhoto||!editor.contains(draggedPhoto))return;e.preventDefault();const img=draggedPhoto;draggedPhoto=null;let target=e.target.nodeType===1?e.target:e.target.parentElement;while(target&&target.parentElement!==editor&&target!==editor)target=target.parentElement;const block=photoBlock(img);if(target&&target!==editor&&target!==block&&!block.contains(target)){const rect=target.getBoundingClientRect();if(e.clientY<rect.top+rect.height/2)target.before(block);else target.after(block)}else if(target===editor)editor.append(block);selectPhoto(img);rememberSelection();update()});
editor.addEventListener('dragend',()=>{draggedPhoto=null});
converter.addRule('sizedPhoto',{filter:n=>n.tagName==='IMG'&&!!n.getAttribute('style'),replacement:(content,node)=>{const copy=node.cloneNode(true);copy.classList.remove('image-selected');copy.removeAttribute('draggable');return copy.outerHTML}});
